fn parse_num(s: &str) -> Result<i64, String> {
    s.parse::<i64>().map_err(|e| e.to_string())
}

fn write_u16<W: Write>(w: &mut W, v: u16) -> io::Result<()> {
    w.write_u16::<LittleEndian>(v)
}

fn collect_nums(xs: &[String]) -> Vec<i32> {
    xs.iter().map(|s| s.parse::<i32>().unwrap_or(0)).collect()
}

fn make_counter() -> impl FnMut() -> i32 {
    let mut n = 0;
    move || { n += 1; n }
}

fn doubles() -> impl Iterator<Item = i32> {
    (0..).map(|x| x * 2)
}

fn dyn_writer() -> Box<dyn Write> {
    Box::new(stdout())
}

fn first<'a>(xs: &'a [i32]) -> Option<&'a i32> {
    xs.iter().next()
}

fn join<'a>(parts: &'a [&'a str], sep: &str) -> String {
    parts.join(sep)
}

fn count(s: &str) -> usize {
    s.chars().count()
}

fn reverse_inplace(xs: &mut Vec<i32>) {
    xs.reverse();
}

fn head(xs: &[i32]) -> Option<i32> {
    xs.first().copied()
}

fn load(path: &str) -> io::Result<String> {
    let mut f = File::open(path)?;
    let mut s = String::new();
    f.read_to_string(&mut s)?;
    Ok(s)
}

fn fetch(url: &str) -> Result<String, reqwest::Error> {
    let body = reqwest::blocking::get(url)?.text()?;
    Ok(body)
}

fn greet(name: Option<String>) -> String {
    if let Some(n) = name {
        format!("hello, {}", n)
    } else {
        "hello".to_string()
    }
}

fn double_opt(x: Option<i32>) -> Option<i32> {
    if let Some(v) = x {
        Some(v * 2)
    } else {
        None
    }
}

fn classify(n: i32) -> &'static str {
    match n {
        0 => "zero",
        n if n > 0 => "positive",
        _ => "negative",
    }
}

fn kind(x: i32) -> &'static str {
    match x {
        1 | 2 | 3 => "small",
        n if n < 100 => "medium",
        _ => "big",
    }
}

fn first_positive(xs: &[i32]) -> Option<i32> {
    xs.iter().find(|&&x| x > 0).copied()
}

fn count_even(xs: &[i32]) -> usize {
    xs.iter().filter(|&&x| x % 2 == 0).count()
}

fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n
}

fn boxed_logger(prefix: String) -> Box<dyn Fn(&str)> {
    Box::new(move |msg| println!("{}: {}", prefix, msg))
}

fn evens_squared(xs: &[i32]) -> Vec<i32> {
    xs.iter().filter(|&&x| x % 2 == 0).map(|&x| x * x).collect()
}

fn sum_positive(xs: &[i32]) -> i32 {
    xs.iter().filter(|&&x| x > 0).sum()
}

trait Speak {
    fn speak(&self) -> String;
}
struct Dog {
    name: String,
}
impl Speak for Dog {
    fn speak(&self) -> String {
        format!("{} barks", self.name)
    }
}

fn greet<T: std::fmt::Display>(x: T) -> String {
    format!("hi, {}", x)
}

fn max<T: PartialOrd>(a: T, b: T) -> T {
    if a > b { a } else { b }
}

fn must_parse(s: &str) -> i32 {
    s.parse().unwrap()
}

fn first_key(m: &HashMap<String, i32>) -> String {
    m.keys().next().unwrap().clone()
}

struct Temp {
    celsius: f64,
}
impl Temp {
    fn fahrenheit(&self) -> f64 {
        self.celsius * 9.0 / 5.0 + 32.0
    }
    fn new(c: f64) -> Self {
        Temp { celsius: c }
    }
}

enum Result<T, E> {
    Ok(T),
    Err(E),
}

enum Shape {
    Circle(f64),
    Rect(f64, f64),
}

fn area(s: Shape) -> f64 {
    match s {
        Shape::Circle(r) => 3.14159 * r * r,
        Shape::Rect(w, h) => w * h,
    }
}

fn get_nested(m: &HashMap<String, Vec<i32>>, k: &str) -> Option<i32> {
    m.get(k).and_then(|xs| xs.first().copied())
}

fn safe_div(a: i32, b: i32) -> Result<i32, String> {
    if b == 0 {
        Err("division by zero".to_string())
    } else {
        Ok(a / b)
    }
}

fn greet(name: &str) {
    println!("Hello, {}!", name);
}

fn debug_dump(label: &str, value: i32) {
    eprintln!("{} = {}", label, value);
}

fn compose(a: &str, b: &str) -> String {
    format!("{}-{}", a, b)
}

fn counter() -> impl FnMut() -> i32 {
    let mut n = 0;
    move || {
        n += 1;
        n
    }
}

fn total(xs: &[i32]) -> i32 {
    xs.iter().copied().sum()
}

fn repeat(s: &str, n: usize) -> String {
    let mut out = String::new();
    for _ in 0..n {
        out.push_str(s);
    }
    out
}

fn squares(n: i32) -> Vec<i32> {
    (0..n).map(|x| x * x).collect()
}
